SELECT e.ENGINEERING_ID AS "engineeringId", e.NAME AS "engineeringName", e.LNG AS "lng", e.LAT AS "lat", e.ADDRESS AS "address", d.ACCESS_DEVICE_ID AS "accessDeviceId", d.DEVICE_NO AS "deviceNo", d.DEVICE_NAME AS "deviceName", d.MONITOR_PLACE AS "monitorPlace", d.DEVICE_STATUS AS "deviceStatus", d.IS_ONLINE AS "isOnline" FROM T_ENGINEERING e INNER JOIN T_ACCESS_DEVICE d ON d.ENGINEERING_ID = e.ENGINEERING_ID WHERE e.IS_DELETE = 0 AND d.IS_DELETE = 0 AND d.DEVICE_TYPE = 1 AND e.ENGINEERING_ID IN
#{id}
ORDER BY e.ENGINEERING_ID, d.ACCESS_DEVICE_ID
